"""Contact sheet for substitute teachers."""

from typing import Iterable, List, Sequence, Tuple

from rosterkit.models import Student
from rosterkit.errors import ProjectError

def _cells(student: Student) -> Tuple[str, str, str]:
    if not (student.email or "").strip():
        raise ProjectError(f"no email for student: {student.display_name}")
    return (student.display_name, student.section, student.email.strip())

def _join_row(cells: Sequence[str], widths: Sequence[int]) -> str:
    padded = (cell.ljust(width) for cell, width in zip(cells, widths))
    return "  ".join(padded).rstrip()

# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Text rows of name, section and email, sorted by name, in columns."""
    people = list(students)
    if not people:
        raise ProjectError("no students to build a contact sheet from")
    people.sort(key=lambda item: (item.display_name.casefold(), item.student_id))
    table = [_cells(person) for person in people]
    widths = [max(len(cell) for cell in column) for column in zip(*table)]
    return [_join_row(cells, widths) for cells in table]

