# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.errors import ProjectError
from rosterkit.contacts import contact_rows

def make_student(ident, last, first, section, email):
    return Student(ident, last, first, section, email)

class ContactRowsTests(unittest.TestCase):
    def test_rows_are_sorted_by_name(self):
        rows = contact_rows([
            make_student("2", "Young", "Zed", "B", "zed@example.com"),
            make_student("1", "adams", "Amy", "A", "amy@example.com"),
        ])
        self.assertTrue(rows[0].startswith("adams, Amy"))
        self.assertTrue(rows[1].startswith("Young, Zed"))

    def test_columns_line_up(self):
        rows = contact_rows([
            make_student("1", "Li", "Al", "A", "al@example.com"),
            make_student("2", "Longername", "Bo", "Blue", "bo@example.com"),
        ])
        self.assertEqual(rows[0].index("A "), rows[1].index("Blue"))
        self.assertEqual(rows[0].index("al@"), rows[1].index("bo@"))
        self.assertEqual(rows[1], "Longername, Bo  Blue  bo@example.com")

    def test_missing_email_names_the_student(self):
        students = [
            make_student("1", "Adams", "Amy", "A", "amy@example.com"),
            make_student("2", "Baker", "Bea", "A", None),
        ]
        with self.assertRaisesRegex(ProjectError, "Baker, Bea"):
            contact_rows(students)

    def test_blank_email_counts_as_missing(self):
        with self.assertRaisesRegex(ProjectError, "Baker, Bea"):
            contact_rows([make_student("2", "Baker", "Bea", "A", "  ")])

    def test_empty_list_raises(self):
        with self.assertRaises(ProjectError):
            contact_rows([])

if __name__ == "__main__":
    unittest.main()
